      "id": 1,
      "claim": "Einstein’s photoelectric equation is KE_max = hν - φ",
      "evidence": "Fundamental result of Einstein’s theory of the photoelectric effect",
      "weight": 0.4,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "The stopping potential V₀ satisfies eV₀ = KE_max",
      "evidence": "By definition, the stopping voltage is the voltage needed to reduce the photocurrent to zero, i.e., to cancel the maximum kinetic energy of the electrons",
      "weight": 0.2,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Therefore V₀ = (h/e)(ν - ν₀) where ν₀ = φ/h is the threshold frequency",
      "evidence": "Substituting KE_max from step 1 into step 2 and solving for V₀",
      "weight": 0.2,
      "depends_on": [1, 2]
    },
    {
      "id": 4,
      "claim": "V₀ is a linear function of the incident light frequency ν for ν > ν₀",
      "evidence": "Equation in step 3 is of the form V₀ = (h/e)·ν - constant, i.e., a straight line with slope h/e",
      "weight": 0.1,
      "depends_on": [3]
    },
    {
      "id": 5,
      "claim": "Option D states exactly this linear relationship",
      "evidence": "Option D: “potential difference necessary to stop the emitted electrons is a linear function of the frequency above the threshold frequency”",
      "weight": 0.05,
      "depends_on": [4]
    },
    {
      "id": 6,
      "claim": "Options A, B, and C contradict the established relations",
      "evidence": "Work function φ is a material constant, not dependent on frequency or wavelength; photocurrent depends on intensity, not wavelength",
      "weight": 0.05,
      "depends_on": [1]
    }
  ],
  "answer": "D",
  "confidence": 0.99,
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "Work function is not proportional to frequency; it is a fixed property of the metal."
    },
    {
      "answer": "B",
      "reason_rejected": "Work function does not vary with wavelength."
    },
